CREATE TYPE "StakeholderEngagement" AS ENUM ('UNAWARE','RESISTANT','NEUTRAL','SUPPORTIVE','LEADING');
CREATE TYPE "IssueStatus" AS ENUM ('OPEN','INVESTIGATING','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TYPE "ChangeRequestStatus" AS ENUM ('SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','DEFERRED','IMPLEMENTED');
CREATE TABLE "Stakeholder" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"productId" TEXT NOT NULL,"name" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT '',"organisationName" TEXT NOT NULL DEFAULT '',"interest" TEXT NOT NULL DEFAULT '',"influence" INTEGER NOT NULL DEFAULT 3,"engagement" "StakeholderEngagement" NOT NULL DEFAULT 'NEUTRAL',"engagementApproach" TEXT NOT NULL DEFAULT '',"ownerLabel" TEXT,"initiativeId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Stakeholder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Issue" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"productId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"severity" "Severity" NOT NULL DEFAULT 'MEDIUM',"status" "IssueStatus" NOT NULL DEFAULT 'OPEN',"impact" TEXT NOT NULL DEFAULT '',"resolution" TEXT NOT NULL DEFAULT '',"ownerLabel" TEXT,"identifiedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"dueAt" TIMESTAMP(3),"initiativeId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Issue_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChangeRequest" ("id" TEXT NOT NULL,"organisationId" TEXT NOT NULL,"productId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"reason" TEXT NOT NULL DEFAULT '',"scopeImpact" TEXT NOT NULL DEFAULT '',"scheduleImpact" TEXT NOT NULL DEFAULT '',"costImpact" TEXT NOT NULL DEFAULT '',"riskImpact" TEXT NOT NULL DEFAULT '',"requestedBy" TEXT NOT NULL DEFAULT '',"status" "ChangeRequestStatus" NOT NULL DEFAULT 'SUBMITTED',"decisionRationale" TEXT NOT NULL DEFAULT '',"ownerLabel" TEXT,"initiativeId" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ChangeRequest_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Stakeholder_organisationId_productId_engagement_idx" ON "Stakeholder"("organisationId","productId","engagement"); CREATE INDEX "Stakeholder_initiativeId_idx" ON "Stakeholder"("initiativeId");
CREATE INDEX "Issue_organisationId_productId_status_severity_idx" ON "Issue"("organisationId","productId","status","severity"); CREATE INDEX "Issue_initiativeId_idx" ON "Issue"("initiativeId");
CREATE INDEX "ChangeRequest_organisationId_productId_status_createdAt_idx" ON "ChangeRequest"("organisationId","productId","status","createdAt"); CREATE INDEX "ChangeRequest_initiativeId_idx" ON "ChangeRequest"("initiativeId");
ALTER TABLE "Stakeholder" ADD CONSTRAINT "Stakeholder_organisationId_fkey" FOREIGN KEY ("organisationId") REFERENCES "Organisation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Stakeholder" ADD CONSTRAINT "Stakeholder_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Stakeholder" ADD CONSTRAINT "Stakeholder_initiativeId_fkey" FOREIGN KEY ("initiativeId") REFERENCES "Initiative"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Issue" ADD CONSTRAINT "Issue_organisationId_fkey" FOREIGN KEY ("organisationId") REFERENCES "Organisation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Issue" ADD CONSTRAINT "Issue_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Issue" ADD CONSTRAINT "Issue_initiativeId_fkey" FOREIGN KEY ("initiativeId") REFERENCES "Initiative"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ChangeRequest" ADD CONSTRAINT "ChangeRequest_organisationId_fkey" FOREIGN KEY ("organisationId") REFERENCES "Organisation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChangeRequest" ADD CONSTRAINT "ChangeRequest_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChangeRequest" ADD CONSTRAINT "ChangeRequest_initiativeId_fkey" FOREIGN KEY ("initiativeId") REFERENCES "Initiative"("id") ON DELETE SET NULL ON UPDATE CASCADE;
